// POST /wrench: a rider pressed the wrench button in the app to report a broken bike.
// SLA-12: the bike leaves service at once, so the feed never shows a reported bike as rentable.
import type { Database } from "bun:sqlite";
import { logEvent } from "./log";

type WrenchReport = { bike_id?: string; fault?: string };
type BikeRow = { bike_id: string; station_id: string };
type StationRow = { depot: string };

export function recordWrench(database: Database, report: WrenchReport) {
  // Unknown bikes are turned away before any write.
  const bike = database.query("SELECT * FROM bikes WHERE bike_id = ?").get(report.bike_id ?? "");
  if (!bike) return { status: 404, body: { error: `no bike called ${report.bike_id}` } };
  const { bike_id, station_id } = bike as BikeRow;
  const station = database.query("SELECT depot FROM stations WHERE station_id = ?").get(station_id);
  const depot = (station as StationRow).depot;
  const reportedAt = new Date().toISOString();
  const fault = report.fault ?? "OTHER";

  // The wrench, its repair job and the disabled flag are kept together or not at all.
  const record = database.transaction(() => {
    const wrench = database
      .query("INSERT INTO wrenches (bike_id, station_id, fault, reported_at) VALUES (?, ?, ?, ?)")
      .run(bike_id, station_id, fault, reportedAt);
    // The wrench row id makes the job id unique, even for two wrenches in the same millisecond.
    const jobId = `J-W-${wrench.lastInsertRowid}`;
    database
      .query("INSERT INTO repair_jobs VALUES (?, ?, ?, ?, 'wrench', ?, ?, ?, NULL)")
      .run(jobId, bike_id, station_id, depot, fault, reportedAt, reportedAt);
    database.query("UPDATE bikes SET is_disabled = 1 WHERE bike_id = ?").run(bike_id);
    return jobId;
  });
  const jobId = record();

  logEvent("wrench", { bike_id, station_id, fault, job_id: jobId });
  return { status: 201, body: { job_id: jobId, bike_id } };
}
// GET /crew/queue?depot=North: the open repair jobs a depot's crews work through, top first.
import type { Database } from "bun:sqlite";

const HOUR = 60 * 60 * 1000;

type JobRow = {
  job_id: string;
  bike_id: string;
  station_id: string;
  source: string;
  fault: string;
  reported_at: string;
  opened_at: string;
};

// SLA-4: 48 hours for a wrench, 96 hours for a defect a crew found itself.
// The clock runs from the report (reported_at), not from when the job was opened.
function contractDeadline(job: JobRow): string {
  const limitHours = job.source === "wrench" ? 48 : 96;
  return new Date(Date.parse(job.reported_at) + limitHours * HOUR).toISOString();
}

export function crewQueue(database: Database, depot: string | null) {
  const jobs = database
    .query("SELECT * FROM repair_jobs WHERE closed_at IS NULL AND (?1 IS NULL OR depot = ?1)")
    .all(depot) as JobRow[];
  const queue = jobs.map((job) => ({ ...job, deadline: contractDeadline(job) }));
  // The job due first goes on top. Ties: earlier report first, then job id.
  queue.sort(
    (first, second) =>
      first.deadline.localeCompare(second.deadline) ||
      first.reported_at.localeCompare(second.reported_at) ||
      first.job_id.localeCompare(second.job_id),
  );
  return { depot: depot ?? "all", jobs: queue };
}
// The public feed in GBFS v3 shape: https://github.com/MobilityData/gbfs/blob/master/gbfs.md
// Rider apps and the city read it. The contract says it must be accurate at all times.
import type { Database } from "bun:sqlite";

const FEED_VERSION = "3.0";
const SECONDS_UNTIL_STALE = 60;

type BikeRow = { bike_id: string; bike_type: string; station_id: string; is_disabled: number };
type StationCount = { station_id: string; docks: number; available: number; disabled: number };

function wrapInFeed(data: object) {
  const lastUpdated = new Date().toISOString();
  return { last_updated: lastUpdated, ttl: SECONDS_UNTIL_STALE, version: FEED_VERSION, data };
}

export function vehicleStatus(database: Database) {
  const bikes = database.query("SELECT * FROM bikes ORDER BY bike_id").all() as BikeRow[];
  const vehicles = bikes.map((bike) => ({
    vehicle_id: bike.bike_id,
    station_id: bike.station_id,
    vehicle_type_id: bike.bike_type,
    is_reserved: false,
    is_disabled: bike.is_disabled === 1,
  }));
  return wrapInFeed({ vehicles });
}

const STATION_COUNTS = `
  SELECT stations.station_id, stations.docks,
    SUM(CASE WHEN bikes.is_disabled = 0 THEN 1 ELSE 0 END) AS available,
    SUM(CASE WHEN bikes.is_disabled = 1 THEN 1 ELSE 0 END) AS disabled
  FROM stations LEFT JOIN bikes ON bikes.station_id = stations.station_id
  GROUP BY stations.station_id ORDER BY stations.station_id`;

export function stationStatus(database: Database) {
  const counts = database.query(STATION_COUNTS).all() as StationCount[];
  const stations = counts.map((count) => ({
    station_id: count.station_id,
    num_vehicles_available: count.available ?? 0,
    num_vehicles_disabled: count.disabled ?? 0,
    num_docks_available: Math.max(0, count.docks - (count.available ?? 0) - (count.disabled ?? 0)),
    is_renting: true,
    is_returning: true,
  }));
  return wrapInFeed({ stations });
}
// spoke's database: stations, bikes, wrenches and repair jobs, in one SQLite file.
// When the file is new, it is filled from the CSV files in data/.
import { Database } from "bun:sqlite";
import { existsSync } from "node:fs";
import { join } from "node:path";
import { readCsv } from "./csv";

const DATA_FOLDER = join(import.meta.dir, "..", "data");
const DATABASE_FILE = process.env.SPOKE_DB ?? join(import.meta.dir, "..", "spoke.db");
const HOUR = 60 * 60 * 1000;

const TABLES = `
  CREATE TABLE stations (station_id TEXT PRIMARY KEY, name TEXT, district TEXT, depot TEXT,
    x INTEGER, y INTEGER, docks INTEGER);
  CREATE TABLE bikes (bike_id TEXT PRIMARY KEY, bike_type TEXT, station_id TEXT,
    is_disabled INTEGER DEFAULT 0);
  CREATE TABLE wrenches (wrench_id INTEGER PRIMARY KEY AUTOINCREMENT, bike_id TEXT,
    station_id TEXT, fault TEXT, reported_at TEXT);
  CREATE TABLE repair_jobs (job_id TEXT PRIMARY KEY, bike_id TEXT, station_id TEXT, depot TEXT,
    source TEXT, fault TEXT, reported_at TEXT, opened_at TEXT, closed_at TEXT);
`;

function fillStationsAndBikes(database: Database) {
  const addStation = database.prepare("INSERT INTO stations VALUES (?, ?, ?, ?, ?, ?, ?)");
  for (const station of readCsv(join(DATA_FOLDER, "stations.csv"))) {
    const mapPosition = [Number(station.x), Number(station.y)];
    const where = [station.station_id, station.name, station.district, station.depot];
    addStation.run(...where, ...mapPosition, Number(station.docks));
  }
  const addBike = database.prepare("INSERT INTO bikes VALUES (?, ?, ?, 0)");
  for (const bike of readCsv(join(DATA_FOLDER, "bikes.csv"))) {
    addBike.run(bike.bike_id, bike.bike_type, bike.station_id);
  }
}

// Open jobs are stored as "hours ago", so the queue looks fresh whenever spoke starts.
function fillOpenJobs(database: Database) {
  const now = Date.now();
  const addJob = database.prepare("INSERT INTO repair_jobs VALUES (?, ?, ?, ?, ?, ?, ?, ?, NULL)");
  const disableBike = database.prepare(
    "UPDATE bikes SET is_disabled = 1, station_id = ? WHERE bike_id = ?",
  );
  for (const job of readCsv(join(DATA_FOLDER, "open-jobs.csv"))) {
    const reportedAt = new Date(now - Number(job.reported_hours_ago) * HOUR).toISOString();
    const openedAt = new Date(now - Number(job.opened_hours_ago) * HOUR).toISOString();
    const { job_id, bike_id, station_id, depot, source, fault } = job;
    addJob.run(job_id, bike_id, station_id, depot, source, fault, reportedAt, openedAt);
    disableBike.run(station_id, bike_id);
  }
}

export function openDatabase(): Database {
  const isNew = !existsSync(DATABASE_FILE);
  const database = new Database(DATABASE_FILE);
  if (isNew) {
    database.exec(TABLES);
    fillStationsAndBikes(database);
    fillOpenJobs(database);
  }
  return database;
}
// Shared setup for the acceptance tests in this folder. Not a test file.
// src/database reads SPOKE_DB and src/log reads SPOKE_LOG when they load, so the paths are set
// to temp files here, before either module is imported (AGENTS.md). Every src/ import below is
// dynamic on purpose: a static `import ... from "../../src/..."` would be hoisted above these lines.
import type { Database } from "bun:sqlite";
import { expect } from "bun:test";
import { tmpdir } from "node:os";
import { join } from "node:path";

const runId = `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
process.env.SPOKE_DB = join(tmpdir(), `spoke-acceptance-${runId}.db`);
process.env.SPOKE_LOG = join(tmpdir(), `spoke-acceptance-${runId}.log`);

const database = await import("../../src/database");
const feed = await import("../../src/feed");
const wrenches = await import("../../src/wrenches");
const map = await import("../../src/map-page");
const queue = await import("../../src/crew-queue");
const csv = await import("../../src/csv");

export const openDatabase = database.openDatabase;
export const recordWrench = wrenches.recordWrench;
export const stationStatus = feed.stationStatus;
export const vehicleStatus = feed.vehicleStatus;
export const mapPage = map.mapPage;
export const crewQueue = queue.crewQueue;
export const readCsv = csv.readCsv;

export const HOUR = 60 * 60 * 1000;

export type QueueJob = {
  job_id: string;
  depot: string;
  source: string;
  reported_at: string;
  opened_at: string;
  deadline: string;
};

/** The station a bike is docked at, from the `bikes` table. */
export function stationOf(db: Database, bikeId: string): string {
  const row = db.query("SELECT station_id FROM bikes WHERE bike_id = ?").get(bikeId) as {
    station_id: string;
  } | null;
  if (!row) throw new Error(`test setup: no bike ${bikeId}`);
  return row.station_id;
}

/** How many rows in `table` belong to `bikeId`. */
export function countRows(db: Database, table: "wrenches" | "repair_jobs", bikeId: string): number {
  const row = db.query(`SELECT COUNT(*) AS n FROM ${table} WHERE bike_id = ?`).get(bikeId) as {
    n: number;
  };
  return row.n;
}

/** The bike's `is_disabled` column (0 or 1). */
export function isDisabledInTable(db: Database, bikeId: string): number {
  const row = db.query("SELECT is_disabled FROM bikes WHERE bike_id = ?").get(bikeId) as {
    is_disabled: number;
  };
  return row.is_disabled;
}

/** Station S's entry in `station_status.json`, read through `stationStatus`. */
export function stationCounts(db: Database, stationId: string) {
  const entry = feed.stationStatus(db).data.stations.find((s) => s.station_id === stationId);
  if (!entry) throw new Error(`test setup: no station ${stationId} in station_status`);
  return {
    available: entry.num_vehicles_available,
    disabled: entry.num_vehicles_disabled,
    docks: entry.num_docks_available,
  };
}

/** SLA-4: the deadline counts from `reported_at`, 48h for a wrench, 96h for anything else. */
export function contractDeadline(job: { source: string; reported_at: string }): string {
  const limitHours = job.source === "wrench" ? 48 : 96;
  return new Date(Date.parse(job.reported_at) + limitHours * HOUR).toISOString();
}

/** AC-9 order: deadline ascending, then reported_at, then job_id. */
export function compareQueueOrder(a: QueueJob, b: QueueJob): number {
  return (
    a.deadline.localeCompare(b.deadline) ||
    a.reported_at.localeCompare(b.reported_at) ||
    a.job_id.localeCompare(b.job_id)
  );
}

/** Asserts that `jobs` is already in AC-9 order. Compares job ids so a failure is readable. */
export function expectQueueOrder(jobs: QueueJob[]) {
  const sorted = [...jobs].sort(compareQueueOrder);
  expect(jobs.map((job) => job.job_id)).toEqual(sorted.map((job) => job.job_id));
}

/** Asserts that every job's deadline follows SLA-4 (AC-8). */
export function expectContractDeadlines(jobs: QueueJob[]) {
  const wrong = jobs
    .filter((job) => job.deadline !== contractDeadline(job))
    .map((job) => `${job.job_id}: got ${job.deadline}, want ${contractDeadline(job)}`);
  expect(wrong).toEqual([]);
}

/** Inserts an open repair job straight into the table, for queue tests. */
export function insertJob(
  db: Database,
  job: { job_id: string; bike_id: string; station_id: string; depot: string; source: string; reported_at: string; opened_at: string },
) {
  db.query("INSERT INTO repair_jobs VALUES (?, ?, ?, ?, ?, 'OTHER', ?, ?, NULL)").run(
    job.job_id,
    job.bike_id,
    job.station_id,
    job.depot,
    job.source,
    job.reported_at,
    job.opened_at,
  );
}
