) {
  db.query("INSERT INTO repair_jobs VALUES (?, ?, ?, ?, ?, 'OTHER', ?, ?, NULL)").run(
    job.job_id,
    job.bike_id,
    job.station_id,
    job.depot,
    job.source,
    job.reported_at,
    job.opened_at,
  );
}
